#!/usr/bin/env node
/**
 * Bundles the vendor's browser license generator into ONE self-contained HTML file
 * (tools/license-generator/ArabPowerTwin-License-Generator.html) so the seller can download a single file from GitHub
 * and open it anywhere offline. Regenerated by `npm run license:bundle` and automatically by `npm run license -- keygen`.
 * Never ship this file to customers.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DIR = path.join(ROOT, 'tools', 'license-generator');
export const BUNDLE_PATH = path.join(DIR, 'ArabPowerTwin-License-Generator.html');

export function buildBundle() {
  const html = fs.readFileSync(path.join(DIR, 'index.html'), 'utf8');
  const js = fs.readFileSync(path.join(DIR, 'license-crypto.js'), 'utf8');
  const version = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version;
  if (!html.includes('<script src="license-crypto.js"></script>')) throw new Error('index.html: script tag not found');
  if (js.includes('</script')) throw new Error('license-crypto.js must not contain a closing script tag');
  return html
    .replace('<!doctype html>', `<!doctype html>\n<!-- Generated from tools/license-generator/index.html + license-crypto.js by scripts/build-license-generator.mjs (npm run license:bundle). Do not edit by hand. Vendor tool - never send to customers. -->`)
    .replace('<script src="license-crypto.js"></script>', () => '<script>\n' + js + '\n</script>')
    .replace('</main>', `  <p class="muted" style="grid-column:1 / -1;text-align:center">License Generator · Arab Power Twin v${version}</p>\n</main>`);
}

export function writeBundle() { const out = buildBundle(); fs.writeFileSync(BUNDLE_PATH, out); return BUNDLE_PATH; }

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const p = writeBundle();
  console.log(`license generator bundled: ${path.relative(ROOT, p)} (${(fs.statSync(p).size / 1024).toFixed(0)} KB)`);
}
